		/**
		 * Tests getting all BenefitEnrollments.
		 */
		public void testGetAll() throws Throwable {    
			LOGGER.info( "======== GETALL ======== ");
			LOGGER.info( "-- Retrieving Collection of BenefitEnrollments:" );

			StringBuilder msg = new StringBuilder( "-- Failed to get all BenefitEnrollment : " );        
			List<BenefitEnrollment> collection  = null;

			try {
				// call the static get method on the BenefitEnrollmentService
				collection = BenefitEnrollmentService.getBenefitEnrollmentInstance().getAllBenefitEnrollment();

				if ( collection == null || collection.size() == 0 ) {
					LOGGER.warning( unexpectedErrorMsg );
					LOGGER.warning( msg.toString() + " Empty collection returned."  );
				}
				else {
					// Now print out the values
					BenefitEnrollment entity = null;            
					Iterator<BenefitEnrollment> iter = collection.iterator();
					int index = 1;

					while( iter.hasNext() ) {
						// Retrieve the entity   
						entity = iter.next();

						assertNotNull( entity,"-- null entity in Collection." );
						assertNotNull( entity.getBenefitEnrollmentId(), "-- entity in Collection has a null primary key" );        

						LOGGER.info( " - " + String.valueOf(index) + ". " + entity.toString() );
						index++;
					}
				}
			}
			catch ( Throwable e ) {
				LOGGER.warning( unexpectedErrorMsg );
				LOGGER.warning( msg.toString() + " : " + e );

				throw e;
			}
		}

